CREATE TABLE IF NOT EXISTS qa_users (id CHAR(36) PRIMARY KEY, email VARCHAR(191) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS qa_quizzes (id CHAR(36) PRIMARY KEY, owner_id CHAR(36) NOT NULL, config_json MEDIUMTEXT NOT NULL, version INT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, FOREIGN KEY(owner_id) REFERENCES qa_users(id), INDEX(owner_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS qa_publications (id CHAR(36) PRIMARY KEY, quiz_id CHAR(36) NOT NULL UNIQUE, owner_id CHAR(36) NOT NULL, slug VARCHAR(32) NOT NULL UNIQUE, active TINYINT NOT NULL DEFAULT 0, live_json MEDIUMTEXT NULL, pending_json MEDIUMTEXT NULL, job_id CHAR(36) NULL, job_started_at BIGINT NULL, github_commit VARCHAR(64) NULL, published_at BIGINT NULL, last_error VARCHAR(255) NULL, created_at BIGINT NOT NULL, FOREIGN KEY(quiz_id) REFERENCES qa_quizzes(id), FOREIGN KEY(owner_id) REFERENCES qa_users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS qa_sessions (id CHAR(36) PRIMARY KEY, owner_id CHAR(36) NOT NULL, quiz_id CHAR(36) NOT NULL, publication_id CHAR(36) NULL, visitor_hash CHAR(64) NULL, mode VARCHAR(8) NOT NULL, snapshot_json MEDIUMTEXT NOT NULL, state_json MEDIUMTEXT NOT NULL, version INT NOT NULL, expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL, FOREIGN KEY(owner_id) REFERENCES qa_users(id), FOREIGN KEY(quiz_id) REFERENCES qa_quizzes(id), FOREIGN KEY(publication_id) REFERENCES qa_publications(id), INDEX(expires_at), INDEX(owner_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS qa_leads (id CHAR(36) PRIMARY KEY, owner_id CHAR(36) NOT NULL, quiz_id CHAR(36) NOT NULL, session_id CHAR(36) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(25) NOT NULL, consent_text TEXT NOT NULL, answers_json MEDIUMTEXT NOT NULL, score INT NOT NULL, result_id CHAR(36) NOT NULL, created_at BIGINT NOT NULL, FOREIGN KEY(owner_id) REFERENCES qa_users(id), FOREIGN KEY(quiz_id) REFERENCES qa_quizzes(id), FOREIGN KEY(session_id) REFERENCES qa_sessions(id), INDEX(owner_id,quiz_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS qa_counters (id CHAR(36) PRIMARY KEY, counter_name VARCHAR(64) NOT NULL UNIQUE, next_value BIGINT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS qa_rate_limits (id CHAR(36) PRIMARY KEY, bucket_key CHAR(64) NOT NULL UNIQUE, hits INT NOT NULL, expires_at BIGINT NOT NULL, INDEX(expires_at)) ENGINE=InnoDB;
